+/* The Notebook/Source view switch — a real sliding toggle (track + thumb over a visually-hidden
+   checkbox), not the topbar's segmented button-group (gramaire-topbar.mjs's Light/Auto/Dark
+   control): that's a 3-way exclusive-choice control, this is a plain two-state switch. */
+.gramaire__view-toggle {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  cursor: pointer;
+  user-select: none;
+}
+.gramaire__view-toggle-label {
+  font-family: var(--font-mono);
+  font-size: 11px;
+  color: var(--fg-faint);
+}
+.gramaire__view-toggle-input {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  overflow: hidden;
+  clip: rect(0 0 0 0);
+  opacity: 0;
+}
+.gramaire__view-toggle-track {
+  position: relative;
+  flex: none;
+  width: 28px;
+  height: 16px;
+  border-radius: 999px;
+  background: var(--border-strong);
+  transition: background 0.15s ease;
+}
+.gramaire__view-toggle-thumb {
+  position: absolute;
+  top: 2px;
+  left: 2px;
+  width: 12px;
+  height: 12px;
+  border-radius: 50%;
+  background: var(--bg);
+  transition: transform 0.15s ease;
+}
+.gramaire__view-toggle-input:checked ~ .gramaire__view-toggle-track {
+  background: var(--accent);
+}
+.gramaire__view-toggle-input:checked
+  ~ .gramaire__view-toggle-track
+  .gramaire__view-toggle-thumb {
+  transform: translateX(12px);
+}
+.gramaire__view-toggle-input:focus-visible ~ .gramaire__view-toggle-track {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+}
+
 /* Layer 1 — the document diagnostics panel. */
 .gramaire__diagnostics {
   flex: none;
